from transformers import BertConfig, BertForSequenceClassification

# Define the transformer model architecture for fake news detection
class TransformerModel(BertForSequenceClassification):
    def __init__(self, config=None, num_labels=2):
        if config is None:
            config = BertConfig.from_pretrained('bert-base-uncased')
        super(TransformerModel, self).__init__(config)
        self.num_labels = num_labels

